async function runProfilePnpm(context, args, options) {
	// DSHA_PLUGIN_UNLOCKED_PNPM_V2: the user's repair/install policy permits
	// dependency and Git prepare hooks. pnpm 10 otherwise refuses Git builds.
	// Keep registry/spec/lock choices; fetch retries repeat only read requests.
	if (process.env.DSHA_PLUGIN_UNLOCKED === "1") options = {
		...options,
		args: [...options.args ?? [],
			"--config.dangerously-allow-all-builds=true", "--config.ignore-scripts=false",
			"--config.ignore-dep-scripts=false", "--config.update-notifier=false",
			"--config.fetch-retries=1", "--config.fetch-retry-mintimeout=1000",
			"--config.fetch-retry-maxtimeout=3000", "--config.fetch-timeout=60000",
			"--reporter=append-only"]
	};

const environment = {
	...options.execution === "cli" ? process.env : scrubbedParentEnv(),
	...options.env
};
// DSHA_PLUGIN_HTTPS_GITHUB_V1: pnpm's hosted-Git probe may choose SSH
// after an intermittent HTTPS error. A browser-supplied HTTPS source
// remains on GitHub HTTPS; this invocation never edits global Git config.
// Existing explicit command-level Git configuration keeps precedence.
if (process.env.DSHA_PLUGIN_UNLOCKED === "1"
	&& namedSpecs(args).some((spec) => /^https:\/\/github\.com\//i.test(spec))
	&& (!environment.GIT_CONFIG_COUNT || environment.GIT_CONFIG_COUNT === "0")) {
	environment.GIT_CONFIG_COUNT = "3";
	for (const [index, prefix] of ["git+ssh://git@github.com/", "ssh://git@github.com/", "git@github.com:"].entries()) {
		environment["GIT_CONFIG_KEY_" + index] = "url.https://github.com/.insteadOf";
		environment["GIT_CONFIG_VALUE_" + index] = prefix;
	}
}

// DSHA_PLUGIN_SINGLE_INSTALL_V1: hooks may already have run before a
// registry error. Never replay the whole unlocked install automatically.
if (process.env.DSHA_PLUGIN_UNLOCKED === "1" || failedAt !== "registry" || index === plan.length - 1) break;
